<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import PaginationControls from '@/components/PaginationControls.vue';
import RequestProgress from '@/components/RequestProgress.vue';
import { api, errorMessage } from '@/api/client';
import { requestStatuses, requestTransitions, requestLabel, canDeleteRequest } from '@/utils/requests';
import type { ApiResponse, DocumentRequest, Pagination, RequestStatus } from '@/types/api';
const route = useRoute();
const props = defineProps<{ admin?: boolean }>();
const requests = ref<DocumentRequest[]>([]), selected = ref<DocumentRequest | null>(null), deleting = ref<DocumentRequest | null>(null), pagination = ref<Pagination | null>(null);
const page = ref(1), status = ref(''), search = ref(''), note = ref(''), nextStatus = ref<RequestStatus | ''>(''), loading = ref(false), busy = ref(false), error = ref(''), notice = ref('');
const transitions = computed(() => selected.value ? requestTransitions[selected.value.status] : []);
async function load(nextPage = 1) { page.value = nextPage; loading.value = true; error.value = ''; try { const response = await api.get<ApiResponse<DocumentRequest[]>>(props.admin ? '/requests' : '/requests/my', { params: { page: page.value, limit: 12, status: status.value || undefined, search: search.value || undefined } }); requests.value = response.data.data; pagination.value = response.data.pagination; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function open(id: string) { busy.value = true; error.value = ''; nextStatus.value = ''; try { selected.value = (await api.get<ApiResponse<DocumentRequest>>(`/requests/${id}`)).data.data; note.value = selected.value.adminNote || ''; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function save(changeStatus: boolean) { if (!selected.value || (changeStatus && !nextStatus.value)) return; busy.value = true; error.value = ''; notice.value = ''; try { const response = await api.patch<ApiResponse<DocumentRequest>>(`/requests/${selected.value.id}/${changeStatus ? 'status' : 'note'}`, { version: selected.value.version, adminNote: note.value || null, ...(changeStatus ? { status: nextStatus.value } : {}) }); selected.value = response.data.data; note.value = selected.value.adminNote || ''; nextStatus.value = ''; notice.value = changeStatus ? 'Request status updated.' : 'Registrar note saved.'; await load(page.value); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function remove() { if (!deleting.value) return; busy.value = true; error.value = ''; try { await api.delete(`/requests/${deleting.value.id}`, { params: { version: deleting.value.version } }); if (selected.value?.id === deleting.value.id) selected.value = null; deleting.value = null; notice.value = 'Request deleted.'; await load(page.value); if (!requests.value.length && page.value > 1) await load(page.value - 1); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
watch(() => props.admin, () => { selected.value = null; deleting.value = null; search.value = ''; status.value = ''; void load(); }, { immediate: true });
watch(() => route.query.request, (reference) => { selected.value = null; if (typeof reference === 'string') void open(reference); }, { immediate: true });
</script>
<template><DashboardLayout><section class="mx-auto max-w-6xl space-y-6 p-5 lg:p-10"><header class="flex flex-wrap items-center justify-between gap-4"><h1 class="text-h1">{{ admin ? 'Document request management' : 'My document requests' }}</h1><RouterLink v-if="!admin" to="/requests/new" class="primary-button">Submit request</RouterLink></header><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><form class="flex flex-wrap items-end gap-4 border bg-white p-5" @submit.prevent="load()"><div class="flex-1"><label for="request-search" class="field-label">Search name, reference, index number or email</label><input id="request-search" v-model.trim="search" class="field-input" maxlength="150"></div><div><label for="request-status" class="field-label">Status</label><select id="request-status" v-model="status" class="field-input"><option value="">All statuses</option><option v-for="item in requestStatuses" :key="item" :value="item">{{ requestLabel(item) }}</option></select></div><button class="secondary-button" :disabled="loading || busy">Search</button></form><p v-if="loading" role="status">Loading requests…</p><div v-else class="overflow-x-auto border bg-white"><table class="w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">{{ admin ? 'Applicant' : 'Document' }}</th><th class="p-4">Status</th><th class="p-4">Submitted</th><th class="p-4">Details</th></tr></thead><tbody><tr v-for="item in requests" :key="item.id" class="border-t"><td class="p-4"><p>{{ admin ? item.fullNameAtGraduation : requestLabel(item.requestType) }}</p><p v-if="admin" class="text-xs text-secondary">{{ requestLabel(item.requestType) }}</p><p class="break-all text-xs text-secondary">{{ item.id }}</p></td><td class="p-4 text-sm">{{ requestLabel(item.status) }}</td><td class="p-4 text-sm">{{ new Date(item.createdAt).toLocaleDateString() }}</td><td class="p-4"><button class="underline" :disabled="busy" @click="open(item.id)">Open request</button></td></tr><tr v-if="!requests.length"><td colspan="4" class="p-6">No matching document requests.</td></tr></tbody></table></div><PaginationControls :page="page" :pagination="pagination" :busy="loading || busy" @change="load"/>
<section v-if="selected" class="space-y-5 border bg-white p-6"><div class="flex flex-wrap justify-between gap-4"><h2 class="text-h2">{{ requestLabel(selected.requestType) }}</h2><div class="flex gap-4"><button class="underline" :disabled="busy" @click="open(selected.id)">Refresh details</button><button class="underline" :disabled="busy" @click="selected = null">Close</button></div></div><p class="break-all text-xs text-secondary">{{ selected.id }}</p><RequestProgress :status="selected.status"/><dl class="grid gap-4 sm:grid-cols-2"><div><dt class="font-semibold">Name at graduation</dt><dd>{{ selected.fullNameAtGraduation }}</dd></div><div><dt class="font-semibold">Graduation year</dt><dd>{{ selected.graduationYear || 'Not provided' }}</dd></div><div><dt class="font-semibold">Student / index number</dt><dd>{{ selected.studentIdOrIndexNumber || 'Not provided' }}</dd></div><div><dt class="font-semibold">Contact phone</dt><dd>{{ selected.contactPhone }}</dd></div><div v-if="admin"><dt class="font-semibold">Account email</dt><dd>{{ selected.user.email }}</dd></div><div><dt class="font-semibold">Submitted</dt><dd>{{ new Date(selected.createdAt).toLocaleString() }}</dd></div><div class="sm:col-span-2"><dt class="font-semibold">Purpose</dt><dd class="whitespace-pre-wrap">{{ selected.purpose }}</dd></div><div class="sm:col-span-2"><dt class="font-semibold">Registrar note</dt><dd class="whitespace-pre-wrap">{{ selected.adminNote || 'No registrar note yet.' }}</dd></div><div v-if="selected.completedAt"><dt class="font-semibold">Completed</dt><dd>{{ new Date(selected.completedAt).toLocaleString() }}</dd></div></dl>
<form v-if="admin" class="space-y-4 border-t pt-5" @submit.prevent="save(true)"><label for="registrar-note" class="field-label">Registrar note (visible to the requester)</label><textarea id="registrar-note" v-model.trim="note" class="field-input" rows="4" maxlength="2000"></textarea><button type="button" class="secondary-button" :disabled="busy" @click="save(false)">Save note without changing status</button><template v-if="transitions.length"><label for="request-next-status" class="field-label">Next status</label><select id="request-next-status" v-model="nextStatus" class="field-input" required><option value="">Select a permitted action</option><option v-for="item in transitions" :key="item" :value="item">{{ requestLabel(item) }}</option></select><button class="primary-button" :disabled="busy || !nextStatus">{{ busy ? 'Updating…' : 'Update request status' }}</button></template><p v-else class="text-sm">This request is completed. Its status cannot change.</p></form>
<button v-if="canDeleteRequest(selected.status, Boolean(admin))" class="text-error underline" :disabled="busy" @click="deleting = selected">Delete request</button></section><section v-if="deleting" class="space-y-4 border border-red-200 bg-white p-6" role="alert"><h2 class="font-semibold">Permanently delete this request?</h2><p class="break-all">{{ deleting.id }}</p><p>{{ admin ? 'This removes the document request record, including its current review notes.' : 'Only submitted or rejected requests can be deleted.' }}</p><div class="flex gap-4"><button class="primary-button" :disabled="busy" @click="remove">Confirm deletion</button><button class="secondary-button" :disabled="busy" @click="deleting = null">Cancel</button></div></section></section></DashboardLayout></template>
